                width: "100%", marginTop: 12, padding: "9px 0",
                borderRadius: T.radiusPill, border: "none", background: brandGrad(T.accent),
                color: T.accentText, fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: T.font,
